+async function createProject(): Promise<{ root: string; configPath: string; bundleDir: string }> {
+  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'cx-bundle-'));
+  const bundleDir = path.join(root, 'dist', 'demo-bundle');
